def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    background = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    def is_filled_diagonal_block(r1, c1, r2, c2):
        # Diagonal pairs inside a fully occupied 2x2 motif are not line seeds.
        for r0 in (r1 - 1, r1):
            for c0 in (c1 - 1, c1):
                if 0 <= r0 < h - 1 and 0 <= c0 < w - 1:
                    coords = [(r0, c0), (r0, c0 + 1),
                              (r0 + 1, c0), (r0 + 1, c0 + 1)]
                    if (r1, c1) in coords and (r2, c2) in coords:
                        if all(grid[r][c] != background for r, c in coords):
                            return True
        return False

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w):
                    continue
                if grid[r2][c2] != color or is_filled_diagonal_block(r, c, r2, c2):
                    continue

                for rr, cc, sr, sc in (
                    (r - dr, c - dc, -dr, -dc),
                    (r2 + dr, c2 + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
